  const fetchMasters = async () => {
    setLoadingMasters(true);
    try {
      // Fetching from Supabase (assuming tables exist based on request)
      const headers = { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}` };

      const [custRes, prodRes] = await Promise.all([
        fetch(`${SUPABASE_URL}/rest/v1/customers?select=*`, { headers }),
        fetch(`${SUPABASE_URL}/rest/v1/products?select=*`, { headers })
      ]);

      if (custRes.ok) setAllCustomers(await custRes.json());
      if (prodRes.ok) setAllProducts(await prodRes.json());
    } catch (err) {
      console.error("Master fetch failed", err);
    } finally {
      setLoadingMasters(false);
    }
