  const loadHistoryFromLocal = () => {
    const saved = localStorage.getItem('ginza_order_history');
    if (saved) {
      const parsed: OrderPayload[] = JSON.parse(saved);
      // Filter for last 5 days
      const fiveDaysAgo = new Date();
      fiveDaysAgo.setDate(fiveDaysAgo.getDate() - 5);
      const filtered = parsed.filter(o => new Date(o.timestamp) >= fiveDaysAgo);
      setHistory(filtered);
    }
  };

