    const found = allCustomers.find(c => c.name.toLowerCase() === val.toLowerCase() || c.customerNo === val);
    if (found) {
      setSelectedCustomer(found);
    } else {
      setSelectedCustomer(prev => ({ ...prev, name: val }));
    }
  };

