                      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-rose-500 outline-none"
                      placeholder="Search Customer..."
                      value={selectedCustomer.name}
                      onChange={(e) => handleCustomerSearch(e.target.value)}
                    />
                    <datalist id="customer-list">
                      {allCustomers.map(c => <option key={c.id} value={c.name}>{c.customerNo}</option>)}
                    </datalist>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Customer No</label>
                      <input readOnly value={selectedCustomer.customerNo} className="w-full bg-slate-100 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium text-slate-500" />
                    </div>
                    <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase ml-1">Order Date</label>
                      <input type="date" value={orderDate} onChange={e => setOrderDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold" />
