import { GoogleGenAI, Type } from "@google/genai";
import { SubmissionPayload } from "../types";

// Fix: Use process.env.API_KEY directly for GoogleGenAI initialization
export const analyzeHistoryTrends = async (history: SubmissionPayload[]): Promise<any> => {
  // Always use process.env.API_KEY directly.
  const apiKey = process.env.API_KEY;
  if (!apiKey) return null;

  const ai = new GoogleGenAI({ apiKey });

  const dataSummary = history.map(h => ({
    date: h.date,
    totalOrder: h.totalOrder,
    totalDispatch: h.totalDispatch,
    efficiency: h.totalOrder > 0 ? (h.totalDispatch / h.totalOrder * 100).toFixed(1) : 0
  }));

  const prompt = `Analyze the historical business data for Ginza Industries Limited:
  Data: ${JSON.stringify(dataSummary)}

  Provide a high-level executive summary, identify 3 specific growth or efficiency trends, and give an overall performance status (excellent, normal, or warning). Response must be in JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            insights: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            status: { type: Type.STRING }
          },
          required: ["summary", "insights", "status"]
        }
      }
    });

    // Fix: Access response.text as a property, not a function
    const resultText = response.text || '{}';
    return JSON.parse(resultText);
  } catch (error) {
    console.error("Gemini Trend Audit Error:", error);
    return null;
  }
};

/**
 * Google Apps Script for Ginza Industries Advanced Order Entry
 * VERSION: 5.0 (Optimized for Order Entry & Orders_Final Sheet)
 * TARGET SHEET: https://docs.google.com/spreadsheets/d/1KTAkc-dJZApXqOMYZXsIxIgSX1HNslaUyw9TVyfilK8/
 */

const SHEET_ID = "1KTAkc-dJZApXqOMYZXsIxIgSX1HNslaUyw9TVyfilK8";

// Fix: Updated doPost to support NEW_ORDER action and target Orders_Final tab
function doPost(e) {
  const lock = LockService.getScriptLock();
  try {
    lock.waitLock(30000); 

    const ss = SpreadsheetApp.openById(SHEET_ID);
    let data;
    try {
      if (e.postData && e.postData.contents) {
        data = JSON.parse(e.postData.contents);
      } else {
        data = JSON.parse(e.parameter.payload);
      }
    } catch (parseErr) {
      return ContentService.createTextOutput("JSON Parse Fail").setMimeType(ContentService.MimeType.TEXT);
    }

    // Handle Advanced Order Entry Submission
    if (data.action === 'NEW_ORDER') {
      const sheet = ss.getSheetByName("Orders_Final") || ss.insertSheet("Orders_Final");

      // Setup Headers if sheet is empty
      if (sheet.getLastRow() === 0) {
        sheet.appendRow([
          "Order ID", 
          "Order Date", 
          "Customer Name", 
          "Customer No", 
          "Sales Person", 
          "Order Remarks", 
          "Timestamp", 
          "Items Summary"
        ]);
      }

      const itemsSummary = data.items.map(it => 
        `${it.department}: ${it.itemName} (${it.quantity} ${it.unit} @ ₹${it.rate})`
      ).join(" | ");

      const row = [
        data.id,
        data.orderDate,
        data.customer.name,
        data.customer.customerNo,
        data.salesPerson.name,
        data.orderRemarks,
        data.timestamp,
        itemsSummary
      ];

      sheet.appendRow(row);
      return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
    }

    // Maintain legacy support for DELETE/UPDATE actions
    if (data.action === 'DELETE') {
      const sheet = ss.getSheets()[0];
      const rows = sheet.getDataRange().getValues();
      for (let i = 0; i < rows.length; i++) {
        if (rows[i][0].toString() === data.id.toString()) {
          sheet.deleteRow(i + 1);
          return ContentService.createTextOutput("Deleted").setMimeType(ContentService.MimeType.TEXT);
        }
      }
    }

    return ContentService.createTextOutput("Action Complete").setMimeType(ContentService.MimeType.TEXT);

  } catch (error) {
    return ContentService.createTextOutput("Error: " + error.toString()).setMimeType(ContentService.MimeType.TEXT);
  } finally {
    lock.releaseLock();
  }
}

function doGet() {
  try {
    const ss = SpreadsheetApp.openById(SHEET_ID);
    const sheet = ss.getSheetByName("Orders_Final") || ss.getSheets()[0];
    const range = sheet.getDataRange();
    if (range.getLastRow() < 1) return ContentService.createTextOutput("[]").setMimeType(ContentService.MimeType.JSON);

    const rows = range.getValues();
    const resultData = rows.slice(1).map(r => ({
      id: r[0],
      date: r[1],
      customer: r[2],
      salesPerson: r[4],
      timestamp: r[6]
    }));

    return ContentService.createTextOutput(JSON.stringify(resultData)).setMimeType(ContentService.MimeType.JSON);
  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({error: error.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}
